-- # Lernfeld 5: Cyberphysische Systeme > ## Softwareplanung > - Prozessphasen

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann die Softwareentwicklung ohne eine definierte Anforderungsanalyse erfolgreich starten?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungen sind Grundlage für Planung"}, {"text": "Ja", "correct": false, "because": "Ohne Basis fehlt Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Implementierungsphase immer die zeitaufwändigste Phase in der Softwareplanung?', 2, '[{"text": "Nein", "correct": true, "because": "Dauer hängt vom Projekt ab"}, {"text": "Ja", "correct": false, "because": "Andere Phasen können länger sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Prozessphasen übersprungen werden, ohne die Softwarequalität zu beeinträchtigen?', 2, '[{"text": "Nein", "correct": true, "because": "Jede Phase hat einen Zweck"}, {"text": "Ja", "correct": false, "because": "Überspringen führt zu Mängeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Wartungsphase Teil der initialen Softwareplanung?', 2, '[{"text": "Nein", "correct": true, "because": "Wartung folgt der Entwicklung"}, {"text": "Ja", "correct": false, "because": "Planung fokussiert Entwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Testphase vor der Implementierung abgeschlossen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Tests erfordern funktionierenden Code"}, {"text": "Ja", "correct": false, "because": "Testen ohne Code unmöglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Phase der Softwareplanung definiert die funktionalen Anforderungen?', 2, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Legt Spezifikationen fest"}, {"text": "Design", "correct": false, "because": "Fokussiert Struktur"}, {"text": "Implementierung", "correct": false, "because": "Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'In welcher Phase wird der Quellcode primär geschrieben?', 3, '[{"text": "Implementierung", "correct": true, "because": "Code wird hier erstellt"}, {"text": "Testen", "correct": false, "because": "Überprüfung, kein Schreiben"}, {"text": "Planung", "correct": false, "because": "Vorbereitung, kein Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase folgt direkt auf die Anforderungsanalyse?', 2, '[{"text": "Design", "correct": true, "because": "Struktur wird geplant"}, {"text": "Testen", "correct": false, "because": "Spätere Phase"}, {"text": "Bereitstellung", "correct": false, "because": "Endphase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase stellt sicher, dass die Software fehlerfrei funktioniert?', 2, '[{"text": "Testen", "correct": true, "because": "Überprüft Funktionalität"}, {"text": "Design", "correct": false, "because": "Planung, kein Test"}, {"text": "Wartung", "correct": false, "because": "Nachbereitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase markiert den Übergang der Software in den produktiven Einsatz?', 2, '[{"text": "Bereitstellung", "correct": true, "because": "Software wird ausgerollt"}, {"text": "Implementierung", "correct": false, "because": "Entwicklung"}, {"text": "Anforderungsanalyse", "correct": false, "because": "Anfang"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zum klassischen Softwareentwicklungsprozess?', 4, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Start mit Spezifikation"}, {"text": "Design", "correct": true, "because": "Strukturplanung"}, {"text": "Marketing", "correct": false, "because": "Kein Entwicklungsaspekt"}, {"text": "Testen", "correct": true, "because": "Qualitätssicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aktivitäten finden in der Designphase statt?', 3, '[{"text": "Erstellen von Architekturdiagrammen", "correct": true, "because": "Definiert Struktur"}, {"text": "Schreiben von Quellcode", "correct": false, "because": "Implementierung"}, {"text": "Planen der Systemstruktur", "correct": true, "because": "Teil des Designs"}, {"text": "Testen von Funktionen", "correct": false, "because": "Testphase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen können Risiken für das Projekt erzeugen?', 3, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Unklare Anforderungen"}, {"text": "Implementierung", "correct": true, "because": "Technische Fehler"}, {"text": "Bereitstellung", "correct": true, "because": "Integrationsprobleme"}, {"text": "Planung", "correct": false, "because": "Vorbereitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind in der Testphase entscheidend?', 4, '[{"text": "Fehlerbehebung", "correct": true, "because": "Korrigiert Probleme"}, {"text": "Testfälle erstellen", "correct": true, "because": "Definiert Überprüfung"}, {"text": "Hardwareauswahl", "correct": false, "because": "Nicht Testaspekt"}, {"text": "Validierung der Anforderungen", "correct": true, "because": "Sichert Zielerfüllung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen erfordern enge Zusammenarbeit mit Stakeholdern?', 3, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Kundenbedürfnisse klären"}, {"text": "Bereitstellung", "correct": true, "because": "Abnahme durch Nutzer"}, {"text": "Design", "correct": false, "because": "Technische Planung"}, {"text": "Testen", "correct": true, "because": "Feedback nötig"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Anforderungsanalyse kann nach der Implementierung angepasst werden. b) Die Testphase schließt die Entwicklung ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anpassung möglich, Testen nicht abschließend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Designphase umfasst die Programmierung der Software. b) Die Bereitstellung erfordert eine funktionierende Software.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Design plant, Bereitstellung setzt voraus"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Implementierung kann ohne Design beginnen. b) Jede Phase hat spezifische Ergebnisse.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Design nötig, Phasen zielgerichtet"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Testphase kann parallel zur Implementierung laufen. b) Die Wartung ist Teil der Entwicklungsphasen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Parallel möglich, Wartung separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Anforderungsanalyse ist optional bei kleinen Projekten. b) Die Designphase definiert die technische Umsetzung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Analyse essenziell, Design technisch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

